import { useEffect, useRef, useState } from 'react';
import { getSupabase, supabaseConfigured } from './lib/supabase';
import { ArrowRight, BookOpen, Check, CheckCircle2, ChevronRight, Code2, Copy, FileText, Flag, Lightbulb, MessageCircle, Plus, Puzzle, RotateCcw, Send, Share2, ShieldCheck, Terminal, Trash2, Users, X, Zap } from 'lucide-react';

type ToastFn = (message: string) => void;
const readLocal = <T,>(key: string, fallback: T): T => { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; } };

type Step = { title: string; detail: string; hint: string };
type Problem = { id: string; title: string; subject: string; level: string; prompt: string; steps: Step[]; answer: string; custom?: boolean };
const starterProblems: Problem[] = [
 {id:'linear',title:'Solve a linear equation',subject:'Mathematics',level:'Beginner',prompt:'Solve: 3x + 7 = 22',steps:[{title:'Isolate x',detail:'Subtract 7 from both sides: 3x = 22 − 7 = 15.',hint:'Undo the addition first.'},{title:'Undo multiplication',detail:'Divide both sides by 3: x = 15 ÷ 3 = 5.',hint:'Which operation reverses multiplication by 3?'},{title:'Verify the result',detail:'Substitute x = 5: 3(5) + 7 = 15 + 7 = 22.',hint:'Put your result back into the original equation.'}],answer:'x = 5'},
 {id:'binary',title:'Trace binary search',subject:'Algorithms',level:'Intermediate',prompt:'Find 23 in [4, 8, 12, 17, 23, 31, 42]. Use zero-based indexing.',steps:[{title:'Inspect the middle',detail:'Middle index 3 contains 17. Since 23 is greater, continue in the right half.',hint:'Compare the target with the middle value.'},{title:'Narrow the range',detail:'The remaining range is [23, 31, 42]. Inspect its middle and eliminate values that cannot contain the target.',hint:'Discard only the half that cannot contain the target.'},{title:'Return the index',detail:'23 is at original index 4.',hint:'Remember that array indexing starts at zero.'}],answer:'Index 4 (value 23)'},
 {id:'logic',title:'Evaluate a logic expression',subject:'Digital Logic',level:'Beginner',prompt:'For A = 1 and B = 0, evaluate (A AND B) OR (NOT B).',steps:[{title:'Evaluate AND',detail:'A AND B = 1 AND 0 = 0.',hint:'AND is 1 only when both inputs are 1.'},{title:'Evaluate NOT',detail:'NOT B = NOT 0 = 1.',hint:'NOT flips a binary value.'},{title:'Evaluate OR',detail:'0 OR 1 = 1. The expression evaluates to 1.',hint:'OR is 1 when at least one input is 1.'}],answer:'1 (True)'}
];

export function SolveSpacePage({onToast}:{onToast:ToastFn}) {
 const [problems,setProblems]=useState<Problem[]>(()=>readLocal('sf_solvespace_items',starterProblems));
 const [selected,setSelected]=useState('linear'); const [revealed,setRevealed]=useState(-1); const [showAnswer,setShowAnswer]=useState(false); const [working,setWorking]=useState(()=>readLocal('sf_working_linear','')); const [completed,setCompleted]=useState<string[]>(()=>readLocal('sf_solvespace_completed',[])); const [showReference,setShowReference]=useState(false); const currentIdRef=useRef('linear');
 const [adding,setAdding]=useState(false); const [title,setTitle]=useState(''); const [subject,setSubject]=useState('Computer Science'); const [prompt,setPrompt]=useState(''); const [filter,setFilter]=useState('All');
 useEffect(()=>{localStorage.setItem('sf_solvespace_items',JSON.stringify(problems));},[problems]);useEffect(()=>{localStorage.setItem('sf_solvespace_completed',JSON.stringify(completed));},[completed]);useEffect(()=>{if(currentIdRef.current)localStorage.setItem(`sf_working_${currentIdRef.current}`,working);},[working]);
 const current=problems.find(p=>p.id===selected)||problems[0]; const subjects=['All',...Array.from(new Set(problems.map(p=>p.subject)))];
 function choose(p:Problem){currentIdRef.current=p.id;setSelected(p.id);setRevealed(-1);setShowAnswer(false);setWorking(readLocal(`sf_working_${p.id}`,''));}
 function add(){if(!title.trim()||!prompt.trim()){onToast('Enter a title and problem statement.');return;}const p:Problem={id:`custom-${Date.now()}`,title:title.trim(),subject,level:'Custom',prompt:prompt.trim(),steps:[{title:'Understand the problem',detail:'Write down the known information, the goal, and any constraints.',hint:'What information is given, and what exactly must be found?'},{title:'Choose a method',detail:'Select a formula, algorithm, or logical rule that fits the problem and explain why it applies.',hint:'Which concept from your notes matches this problem?'},{title:'Work through and verify',detail:'Solve one step at a time and check the result against the original conditions.',hint:'Can you verify the result using substitution or a test case?'}],answer:'Use your working notes to record and verify the final answer.',custom:true};setProblems(old=>[p,...old]);choose(p);setTitle('');setPrompt('');setAdding(false);onToast('Problem added.');}
 return <div className="feature-page"><div className="page-intro"><div><div className="eyebrow">THINK IT THROUGH</div><h1>SolveSpace</h1><p>A guided workspace for solving problems step by step, with hints before solutions.</p></div><button className="btn btn-primary" onClick={()=>setAdding(v=>!v)}><Plus size={16}/>{adding?'Close form':'Add a problem'}</button></div>
 <div className="feature-hero solvespace-hero"><div className="feature-hero-icon"><Puzzle size={25}/></div><div><span className="feature-kicker">YOUR WORKING SPACE</span><h2>Progress over shortcuts.</h2><p>Try a step, reveal a hint, and open the worked solution when you're ready.</p></div><div className="feature-hero-metric"><strong>{completed.length}/{problems.length}</strong><span>problems completed</span></div></div><div className="solve-progress-strip"><div><strong>Your solving progress</strong><span>{completed.length} of {problems.length} problems marked solved</span></div><div className="progress-track"><span style={{width:`${problems.length?completed.filter(id=>problems.some(p=>p.id===id)).length/problems.length*100:0}%`}}/></div><button className="btn btn-secondary btn-small" onClick={()=>setShowReference(v=>!v)}><BookOpen size={14}/>{showReference?'Hide quick reference':'Quick reference'}</button></div>{showReference&&<section className="panel solve-reference-panel"><div><strong>Algebra</strong><p>Undo operations in reverse order; always verify by substitution.</p></div><div><strong>Algorithms</strong><p>Define the input, output, invariant, and edge cases before tracing.</p></div><div><strong>Complexity</strong><p>Count dominant operations: one pass is often O(n); nested passes are often O(n²).</p></div><div><strong>Digital logic</strong><p>AND needs both 1, OR needs at least one 1, and NOT flips the input.</p></div></section>}
 {adding&&<section className="panel feature-form-panel"><div className="panel-heading"><div><h3>Add your own problem</h3><p>Save a question and use a structured solving workflow.</p></div><button className="icon-btn" onClick={()=>setAdding(false)}><X size={17}/></button></div><div className="feature-form-grid"><label>Problem title<input className="input-field" value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Calculate time complexity"/></label><label>Subject<select className="select-field" value={subject} onChange={e=>setSubject(e.target.value)}><option>Computer Science</option><option>Mathematics</option><option>Algorithms</option><option>Digital Logic</option><option>Physics</option><option>General</option></select></label><label className="wide-field">Problem statement<textarea className="input-field feature-textarea" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Enter the question, values, or requirements..."/></label></div><div className="feature-form-actions"><button className="btn btn-primary" onClick={add}>Save problem <Check size={16}/></button></div></section>}
 <div className="solvespace-layout"><section className="panel problem-list-panel"><div className="panel-heading"><div><h3>Problem library</h3><p>Choose an example or your saved prompt.</p></div><BookOpen size={18}/></div><div className="filter-pills">{subjects.map(s=><button key={s} className={`filter-pill ${filter===s?'active':''}`} onClick={()=>setFilter(s)}>{s}</button>)}</div><div className="problem-list">{problems.filter(p=>filter==='All'||p.subject===filter).map(p=><button key={p.id} className={`problem-list-item ${p.id===selected?'active':''}`} onClick={()=>choose(p)}><span className="problem-item-icon"><Puzzle size={17}/></span><span className="problem-item-copy"><strong>{p.title}</strong><small>{p.subject} · {p.level}</small></span>{completed.includes(p.id)&&<CheckCircle2 size={15} className="solved-mark"/>}<ChevronRight size={16}/></button>)}</div></section>
 {current&&<section className="panel solve-workspace"><div className="solve-title-row"><div><span className="feature-kicker">{current.subject.toUpperCase()} · {current.level.toUpperCase()}</span><h2>{current.title}</h2></div>{current.custom&&<button className="icon-btn" title="Delete problem" onClick={()=>{setProblems(old=>old.filter(p=>p.id!==current.id));setSelected(starterProblems[0].id);setRevealed(-1);onToast('Custom problem deleted.');}}><Trash2 size={17}/></button>}</div><div className="problem-statement"><span className="statement-label">PROBLEM</span><p>{current.prompt}</p></div><label className="field-label approach-label">Your approach / working notes</label><textarea className="input-field feature-textarea approach-input" value={working} onChange={e=>setWorking(e.target.value)} placeholder="Write what you know, the rule you're using, and your next step..."/><div className="solve-actions"><button className="btn btn-secondary" onClick={()=>{if(!working.trim()){onToast('Write a few lines first.');return;}localStorage.setItem(`sf_working_${current.id}`,working);onToast('Working notes saved.');}}><Check size={15}/> Save working</button><button className="btn btn-ghost" onClick={()=>{setWorking('');setRevealed(-1);setShowAnswer(false);}}>Reset attempt <RotateCcw size={15}/></button><button className="btn btn-secondary" onClick={()=>{setCompleted(old=>old.includes(current.id)?old.filter(id=>id!==current.id):[...old,current.id]);onToast(completed.includes(current.id)?'Problem removed from completed list.':'Problem marked as solved!');}}><CheckCircle2 size={15}/>{completed.includes(current.id)?'Solved · undo':'Mark as solved'}</button></div><div className="solution-heading"><div><h3>Guided steps</h3><p>Reveal explanations only when you're ready.</p></div><span className="step-count">{Math.max(0,revealed+1)} / {current.steps.length}</span></div><div className="guided-steps">{current.steps.map((step,i)=><div key={`${current.id}-${i}`} className={`guided-step ${i<=revealed?'step-open':''}`}><div className="guided-step-head"><span className="step-number">{i+1}</span><div><strong>{step.title}</strong><p>{i<=revealed?step.detail:'Try this step yourself before revealing the explanation.'}</p></div></div>{i>revealed&&<button className="hint-button" onClick={()=>onToast(`Hint: ${step.hint}`)}><Lightbulb size={14}/> Reveal hint</button>}</div>)}</div><div className="solution-footer"><button className="btn btn-primary" onClick={()=>setRevealed(i=>Math.min(current.steps.length-1,i+1))} disabled={revealed>=current.steps.length-1}><ArrowRight size={15}/> Reveal next step</button><button className="btn btn-secondary" onClick={()=>setShowAnswer(v=>!v)}>{showAnswer?'Hide final answer':'Reveal final answer'}</button></div>{showAnswer&&<div className="final-answer-box"><CheckCircle2 size={18}/><div><strong>Worked result</strong><p>{current.answer}</p></div></div>}</section>}</div>
 <div className="feature-info-note"><ShieldCheck size={17}/><span>Custom prompts get a structured solving workflow; the included worked examples have verified sample explanations. Always check answers against your course material.</span></div></div>;
}

type Message={id:string;sender:string;text:string;time:string}; type CheckItem={id:string;text:string;done:boolean}; type Room={code:string;name:string;subject:string;members:string[];messages:Message[];notes:string;tasks:CheckItem[]}; type Poll={id:string;question:string;options:string[];votes:Record<string,number>};
const starterRoom:Room={code:'BIO204',name:'Biology revision',subject:'Biology',members:['Learner'],messages:[{id:'welcome',sender:'Learner',text:'Welcome! Share a question or useful explanation to get started.',time:'Just now'}],notes:'Today we will revise key definitions, diagrams, and process steps.',tasks:[{id:'t1',text:'Review key terms',done:false},{id:'t2',text:'Explain one concept to the group',done:false}]};
function mapCloudRoom(raw:any,currentUserId:string,currentName:string):Room{
 const memberships=Array.isArray(raw.study_room_members)?raw.study_room_members:[];
 const messages=Array.isArray(raw.study_room_messages)?raw.study_room_messages:[];
 return {
  code:String(raw.invite_code),name:String(raw.name),subject:String(raw.subject||'General'),
  members:Array.from(new Set([currentName,...memberships.map((m:any)=>m.user_id===currentUserId?currentName:'Study partner')])),
  messages:messages.sort((a:any,b:any)=>new Date(a.created_at).getTime()-new Date(b.created_at).getTime()).map((m:any)=>({
   id:String(m.id),sender:m.user_id===currentUserId?currentName:'Study partner',text:String(m.message),
   time:new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})
  })),
  notes:String(raw.notes||''),tasks:Array.isArray(raw.tasks)?raw.tasks:[],
 };
}

export function StudySyncPage({userName,onToast}:{userName:string;onToast:ToastFn}){
 const [rooms,setRooms]=useState<Room[]>(()=>readLocal('sf_studysync_rooms',[{...starterRoom,members:[userName||'Learner']} ]));const [activeCode,setActiveCode]=useState(()=>readLocal('sf_studysync_active','BIO204'));const [newName,setNewName]=useState('');const [subject,setSubject]=useState('Computer Science');const [joinCode,setJoinCode]=useState('');const [message,setMessage]=useState('');const [newTask,setNewTask]=useState('');const [roomSearch,setRoomSearch]=useState('');const [messageSearch,setMessageSearch]=useState('');const [pollQuestion,setPollQuestion]=useState('');const [pollOptions,setPollOptions]=useState('Option A, Option B');const [polls,setPolls]=useState<Record<string,Poll[]>>(()=>readLocal('sf_studysync_polls',{}));
 const room=rooms.find(r=>r.code===activeCode)||rooms[0];
 useEffect(()=>{localStorage.setItem('sf_studysync_rooms',JSON.stringify(rooms));},[rooms]);
 useEffect(()=>{localStorage.setItem('sf_studysync_active',JSON.stringify(activeCode));},[activeCode]);
 useEffect(()=>{localStorage.setItem('sf_studysync_polls',JSON.stringify(polls));},[polls]);
 async function refreshCloudRooms(selectCode?:string){
  if(!supabaseConfigured)return;
  const supabase=getSupabase();if(!supabase)return;
  const {data:{user},error:userError}=await supabase.auth.getUser();
  if(userError||!user)return;
  const {data,error}=await supabase.from('study_rooms').select('id,name,subject,invite_code,description,notes,tasks,polls,owner_id,study_room_members(user_id),study_room_messages(id,user_id,message,created_at)').order('created_at',{ascending:false});
  if(error){onToast(`StudySync sync failed: ${error.message}`);return;}
  const mapped=(data||[]).map((r:any)=>mapCloudRoom(r,user.id,userName||'Learner'));
  if(mapped.length){setRooms(mapped);const code=selectCode||activeCode;setActiveCode(mapped.some(r=>r.code===code)?code:mapped[0].code);const nextPolls:Record<string,Poll[]>={};for(const r of (data||[]) as any[]){nextPolls[r.invite_code]=Array.isArray(r.polls)?r.polls:[];}setPolls(old=>({...old,...nextPolls}));}
  else setRooms(old=>old.filter(r=>r.code==='BIO204'));
 }
 useEffect(()=>{
  if(!supabaseConfigured)return;
  let cancelled=false;let channel:any=null;
  const init=async()=>{
   const supabase=getSupabase();if(!supabase)return;
   const {data:{user}}=await supabase.auth.getUser();if(!user||cancelled)return;
   const {data,error}=await supabase.from('study_rooms').select('id,name,subject,invite_code,description,notes,tasks,polls,owner_id,study_room_members(user_id),study_room_messages(id,user_id,message,created_at)').order('created_at',{ascending:false});
   if(error){console.error('StudySync cloud load:',error.message);return;}
   if(cancelled)return;
   const mapped=(data||[]).map((r:any)=>mapCloudRoom(r,user.id,userName||'Learner'));
   if(mapped.length){setRooms(mapped);setActiveCode(old=>mapped.some(r=>r.code===old)?old:mapped[0].code);const nextPolls:Record<string,Poll[]>={};for(const r of (data||[]) as any[]){nextPolls[r.invite_code]=Array.isArray(r.polls)?r.polls:[];}setPolls(old=>({...old,...nextPolls}));}
   const active=(data||[]).find((r:any)=>r.invite_code===activeCode);
   if(active){
    channel=supabase.channel(`study-room-${active.id}`).on('postgres_changes',{event:'*',schema:'public',table:'study_room_messages',filter:`room_id=eq.${active.id}`},()=>{void refreshCloudRooms(active.invite_code);}).subscribe();
   }
  };
  void init();
  return ()=>{cancelled=true;if(channel){const supabase=getSupabase();if(supabase)void supabase.removeChannel(channel);}};
 },[activeCode,userName]);
 useEffect(()=>{const listener=(e:StorageEvent)=>{if(e.key==='sf_studysync_rooms'&&e.newValue){try{setRooms(JSON.parse(e.newValue));}catch{}}if(e.key==='sf_studysync_polls'&&e.newValue){try{setPolls(JSON.parse(e.newValue));}catch{}}};window.addEventListener('storage',listener);return()=>window.removeEventListener('storage',listener);},[]);
 useEffect(()=>{
  if(!supabaseConfigured||!room)return;
  const supabase=getSupabase();if(!supabase)return;
  let cancelled=false;
  void (async()=>{const {data:{user}}=await supabase.auth.getUser();if(!user||cancelled)return;const {data}=await supabase.from('study_rooms').select('id').eq('invite_code',room.code).maybeSingle();if(!data||cancelled)return;await supabase.from('study_rooms').update({polls:polls[room.code]||[]}).eq('id',data.id);})();
  return ()=>{cancelled=true;};
 },[polls,activeCode]);
 async function createRoom(){
 if(!newName.trim()){onToast('Enter a room name first.');return;}
 if(supabaseConfigured){
  const supabase=getSupabase();if(!supabase){onToast('Supabase is not configured correctly.');return;}
  const {data:{user}}=await supabase.auth.getUser();if(!user){onToast('Log in with Supabase to create a shared room.');return;}
  const {data,error}=await supabase.from('study_rooms').insert({owner_id:user.id,name:newName.trim(),subject,description:`StudySync room for ${subject}`,notes:'',tasks:[],polls:[]}).select('id,name,subject,invite_code,description,notes,tasks,polls,owner_id').single();
  if(error||!data){onToast(`Could not create room: ${error?.message||'unknown error'}`);return;}
  const {error:memberError}=await supabase.from('study_room_members').insert({room_id:data.id,user_id:user.id,role:'owner'});
  if(memberError){onToast(`Room created, but membership setup failed: ${memberError.message}`);return;}
  const r:Room={code:data.invite_code,name:data.name,subject:data.subject,members:[userName],messages:[],notes:data.notes||'',tasks:data.tasks||[]};
  setRooms(old=>[r,...old.filter(x=>x.code!==r.code)]);setActiveCode(r.code);setNewName('');onToast(`Shared room created. Invite code: ${r.code}`);return;
 }
 const code=Math.random().toString(36).slice(2,8).toUpperCase();const r:Room={code,name:newName.trim(),subject,members:[userName],messages:[{id:crypto.randomUUID(),sender:userName,text:'Room created. Introduce your topic and share useful explanations here.',time:'Now'}],notes:'',tasks:[]};setRooms(old=>[r,...old]);setActiveCode(code);setNewName('');onToast(`Demo room created. Invite code: ${code}`);
}
 async function join(){
 const code=joinCode.trim().toUpperCase();if(!code){onToast('Enter an invite code.');return;}
 if(supabaseConfigured){
  const supabase=getSupabase();if(!supabase){onToast('Supabase is not configured correctly.');return;}
  const {data:{user}}=await supabase.auth.getUser();if(!user){onToast('Log in with Supabase to join a shared room.');return;}
  const {data,error}=await supabase.rpc('join_room_by_code',{p_invite_code:code});
  if(error){onToast(`Could not join room: ${error.message}`);return;}
  const joined=Array.isArray(data)?data[0]:data;if(!joined){onToast('No room found for that invite code.');return;}
  setJoinCode('');await refreshCloudRooms(joined.invite_code);setActiveCode(joined.invite_code);onToast(`Joined ${joined.name}.`);return;
 }
 const found=rooms.find(r=>r.code===code);if(!found){onToast('That invite code is not saved in this browser. Connect Supabase to join across devices.');return;}if(!found.members.includes(userName))setRooms(old=>old.map(r=>r.code===code?{...r,members:[...r.members,userName]}:r));setActiveCode(code);setJoinCode('');onToast(`Joined ${found.name}.`);
}
 async function send(){
 if(!room||!message.trim())return;
 if(supabaseConfigured){
  const supabase=getSupabase();if(!supabase){onToast('Supabase is not configured correctly.');return;}
  const {data:{user}}=await supabase.auth.getUser();if(!user){onToast('Log in with Supabase to send shared messages.');return;}
  const {data:dbRoom,error:roomError}=await supabase.from('study_rooms').select('id').eq('invite_code',room.code).maybeSingle();
  if(roomError||!dbRoom){onToast('Could not find this shared room.');return;}
  const {data,error}=await supabase.from('study_room_messages').insert({room_id:dbRoom.id,user_id:user.id,message:message.trim()}).select('id,user_id,message,created_at').single();
  if(error||!data){onToast(`Message failed: ${error?.message||'unknown error'}`);return;}
  const m:Message={id:data.id,sender:userName,text:data.message,time:new Date(data.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})};
  setRooms(old=>old.map(r=>r.code===room.code?{...r,messages:[...r.messages,m]}:r));setMessage('');return;
 }
 const m:Message={id:crypto.randomUUID(),sender:userName,text:message.trim(),time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})};setRooms(old=>old.map(r=>r.code===room.code?{...r,messages:[...r.messages,m]}:r));setMessage('');
}
 async function updateRoom(patch:Partial<Room>){
 if(!room)return;setRooms(old=>old.map(r=>r.code===room.code?{...r,...patch}:r));
 if(supabaseConfigured&&(patch.notes!==undefined||patch.tasks!==undefined)){
  const supabase=getSupabase();if(!supabase)return;
  const {data:{user}}=await supabase.auth.getUser();if(!user){onToast('Log in to save shared room changes.');return;}
  const cloudPatch:any={};if(patch.notes!==undefined)cloudPatch.notes=patch.notes;if(patch.tasks!==undefined)cloudPatch.tasks=patch.tasks;
  const {error}=await supabase.from('study_rooms').update(cloudPatch).eq('invite_code',room.code);
  if(error)onToast(`Could not sync room changes: ${error.message}`);
 }
}
 async function copyCode(){try{await navigator.clipboard.writeText(room.code);onToast('Invite code copied.');}catch{onToast(`Share this invite code: ${room.code}`);}}
 function addTask(){if(!newTask.trim()||!room)return;updateRoom({tasks:[...room.tasks,{id:crypto.randomUUID(),text:newTask.trim(),done:false}]});setNewTask('');}
 function createPoll(){if(!room||!pollQuestion.trim()){onToast('Enter a poll question.');return;}const options=pollOptions.split(',').map(v=>v.trim()).filter(Boolean).slice(0,5);if(options.length<2){onToast('Add at least two comma-separated options.');return;}const p:Poll={id:crypto.randomUUID(),question:pollQuestion.trim(),options,votes:{}};setPolls(old=>({...old,[room.code]:[...(old[room.code]||[]),p]}));setPollQuestion('');onToast('Poll added to this room.');}
 function votePoll(pollId:string,index:number){if(!room)return;setPolls(old=>({...old,[room.code]:(old[room.code]||[]).map(p=>p.id===pollId?{...p,votes:{...p.votes,[userName]:index}}:p)}));}
 function exportNotes(){if(!room)return;const content=`${room.name} (${room.code})\n${room.subject}\n\nSHARED NOTES\n${room.notes}\n\nREVISION TASKS\n${room.tasks.map(t=>`${t.done?'[x]':'[ ]'} ${t.text}`).join('\n')}\n\nDISCUSSION\n${room.messages.map(m=>`[${m.time}] ${m.sender}: ${m.text}`).join('\n')}`;const blob=new Blob([content],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${room.code}-study-room.txt`;a.click();URL.revokeObjectURL(url);onToast('Room notes exported.');}
 return <div className="feature-page"><div className="page-intro"><div><div className="eyebrow">LEARN TOGETHER</div><h1>StudySync</h1><p>Shared study rooms for discussion, group notes, and revision tasks.</p></div><button className="btn btn-primary" onClick={()=>document.getElementById('sync-create')?.scrollIntoView({behavior:'smooth',block:'center'})}><Plus size={16}/> Create room</button></div>
 <div className="feature-hero studysync-hero"><div className="feature-hero-icon"><Users size={25}/></div><div><span className="feature-kicker">COLLABORATIVE WORKSPACE</span><h2>Better together.</h2><p>Keep group notes, questions, and revision tasks in one room.</p></div><div className="feature-hero-metric"><strong>{rooms.length}</strong><span>rooms in this browser</span></div></div>
 <div className="studysync-top-grid"><section className="panel feature-form-panel" id="sync-create"><div className="panel-heading"><div><h3>Create a room</h3><p>Set up a subject space and share its code.</p></div><Plus size={18}/></div><label>Room name<input className="input-field" value={newName} onChange={e=>setNewName(e.target.value)} placeholder="e.g. DSA study group"/></label><label>Subject<select className="select-field" value={subject} onChange={e=>setSubject(e.target.value)}><option>Computer Science</option><option>Mathematics</option><option>Physics</option><option>Biology</option><option>Engineering</option><option>General</option></select></label><button className="btn btn-primary full-width" onClick={createRoom}><Plus size={15}/> Create study room</button></section><section className="panel feature-form-panel"><div className="panel-heading"><div><h3>Join a room</h3><p>Enter an invite code available in this browser.</p></div><Share2 size={18}/></div><label>Invite code<input className="input-field uppercase-field" value={joinCode} onChange={e=>setJoinCode(e.target.value)} placeholder="e.g. BIO204"/></label><button className="btn btn-secondary full-width" onClick={join}>Join room <ArrowRight size={15}/></button><div className="feature-info-mini"><ShieldCheck size={15}/> Local demo mode · same browser storage</div></section></div>
 {room&&<div className="studysync-layout"><section className="panel room-sidebar"><div className="panel-heading"><div><h3>Your rooms</h3><p>Select a study group.</p></div><Users size={18}/></div><div className="room-list"><input className="input-field room-search-input" value={roomSearch} onChange={e=>setRoomSearch(e.target.value)} placeholder="Search rooms…"/>{rooms.filter(r=>`${r.name} ${r.subject} ${r.code}`.toLowerCase().includes(roomSearch.toLowerCase())).map(r=><button key={r.code} className={`room-list-item ${activeCode===r.code?'active':''}`} onClick={()=>setActiveCode(r.code)}><span className="room-avatar"><Users size={16}/></span><span><strong>{r.name}</strong><small>{r.subject} · {r.members.length} member{r.members.length===1?'':'s'}</small></span><ChevronRight size={15}/></button>)}</div></section>
 <section className="panel room-main"><div className="room-heading"><div><div className="room-heading-title"><h2>{room.name}</h2><span className="room-code">{room.code}</span></div><p>{room.subject} · {room.members.length} member{room.members.length===1?'':'s'}</p></div><div className="room-heading-actions"><button className="btn btn-secondary btn-small" onClick={exportNotes}><FileText size={14}/> Export</button><button className="btn btn-secondary btn-small" onClick={copyCode}><Copy size={14}/> Invite</button></div></div><div className="room-tabs"><span className="room-tab-active"><MessageCircle size={15}/> Discussion</span><span><FileText size={15}/> Shared notes</span><span><CheckCircle2 size={15}/> Tasks</span></div><div className="room-discussion-toolbar"><input className="input-field" value={messageSearch} onChange={e=>setMessageSearch(e.target.value)} placeholder="Search discussion messages…"/><span>{room.messages.filter(m=>m.text.toLowerCase().includes(messageSearch.toLowerCase())).length} messages</span></div><div className="room-discussion">{room.messages.filter(m=>m.text.toLowerCase().includes(messageSearch.toLowerCase())).map(m=><div className="room-message" key={m.id}><div className="room-message-avatar">{m.sender.slice(0,1).toUpperCase()}</div><div className="room-message-content"><div><strong>{m.sender}</strong><small>{m.time}</small></div><p>{m.text}</p></div></div>)}</div><form className="room-message-form" onSubmit={e=>{e.preventDefault();send();}}><input className="input-field" value={message} onChange={e=>setMessage(e.target.value)} placeholder="Share a question or explanation..."/><button className="btn btn-primary" type="submit" disabled={!message.trim()}><Send size={15}/></button></form><div className="room-bottom-grid"><div><div className="panel-heading"><div><h3>Shared notes</h3><p>Saved automatically.</p></div><FileText size={17}/></div><textarea className="input-field feature-textarea shared-notes" value={room.notes} onChange={e=>updateRoom({notes:e.target.value})} placeholder="Write definitions, examples, and summaries..."/></div><div><div className="panel-heading"><div><h3>Revision checklist</h3><p>Keep the group on track.</p></div><CheckCircle2 size={18}/></div><div className="room-checklist">{room.tasks.map(t=><label key={t.id} className={t.done?'checklist-done':''}><input type="checkbox" checked={t.done} onChange={()=>updateRoom({tasks:room.tasks.map(x=>x.id===t.id?{...x,done:!x.done}:x)})}/><span>{t.text}</span></label>)}</div><form className="add-check-form" onSubmit={e=>{e.preventDefault();addTask();}}><input className="input-field" value={newTask} onChange={e=>setNewTask(e.target.value)} placeholder="Add a revision task"/><button className="icon-btn" type="submit" aria-label="Add task"><Plus size={17}/></button></form></div></div><section className="panel room-polls-panel"><div className="panel-heading"><div><h3>Quick polls</h3><p>Choose a revision topic or check group understanding.</p></div><MessageCircle size={18}/></div><form className="room-poll-form" onSubmit={e=>{e.preventDefault();createPoll();}}><label>Poll question<input className="input-field" value={pollQuestion} onChange={e=>setPollQuestion(e.target.value)} placeholder="e.g. Which topic should we revise next?"/></label><label>Options <small>(separate with commas)</small><input className="input-field" value={pollOptions} onChange={e=>setPollOptions(e.target.value)} placeholder="Option A, Option B, Option C"/></label><button className="btn btn-primary" type="submit"><Plus size={15}/> Create poll</button></form><div className="room-polls-list">{(polls[room.code]||[]).length===0?<p className="empty-poll-copy">No polls yet. Create one to get the group talking.</p>:(polls[room.code]||[]).map(p=>{const total=Object.keys(p.votes).length;const selected=p.votes[userName];return <article className="room-poll-card" key={p.id}><strong>{p.question}</strong><small>{total} vote{total===1?'':'s'}</small><div className="room-poll-options">{p.options.map((option,i)=>{const votes=Object.values(p.votes).filter(v=>v===i).length;const percent=total?Math.round(votes/total*100):0;return <button key={option} className={`room-poll-option ${selected===i?'selected':''}`} onClick={()=>votePoll(p.id,i)}><span>{option}</span><span className="poll-option-result">{total?`${percent}% · ${votes}`:'Vote'}</span><i style={{width:`${percent}%`}}/></button>;})}</div></article>;})}</div></section></section></div>}
 <div className="feature-info-note"><ShieldCheck size={17}/><span>StudySync rooms, messages, notes, and tasks persist in this browser and update across tabs on the same origin. Cross-device, real multi-user collaboration requires a shared backend such as Supabase.</span></div></div>;
}

type TestCase={input:string;expected:string};
type Challenge={id:string;title:string;topic:string;level:string;description:string;examples:string;starter:{javascript:string;python:string;c:string};tests:TestCase[];hint:string};
const challenges:Challenge[]=[
{id:'sum',title:'Add two numbers',topic:'Input / output',level:'Beginner',description:'Read two integers and print their sum.',examples:'Input: 3 4 → Output: 7',starter:{javascript:"const fs = require('fs');\nconst [a, b] = fs.readFileSync(0, 'utf8').trim().split(/\\s+/).map(Number);\nconsole.log(a + b);",python:"a, b = map(int, input().split())\nprint(a + b)",c:'#include <stdio.h>\nint main(void) { int a,b; if(scanf("%d %d", &a, &b)!=2) return 0; printf("%d\\n", a+b); return 0; }'},tests:[{input:'3 4',expected:'7'},{input:'-2 5',expected:'3'},{input:'0 0',expected:'0'}],hint:'Read both values as numbers, then use the + operator.'},
{id:'even',title:'Even or odd',topic:'Conditionals',level:'Beginner',description:'Read an integer and print Even or Odd.',examples:'Input: 8 → Output: Even',starter:{javascript:"const fs = require('fs');\nconst n = Number(fs.readFileSync(0, 'utf8').trim());\nconsole.log(n % 2 === 0 ? 'Even' : 'Odd');",python:"n = int(input())\nprint('Even' if n % 2 == 0 else 'Odd')",c:'#include <stdio.h>\nint main(void) { int n; if(scanf("%d", &n)!=1) return 0; puts(n%2==0 ? "Even" : "Odd"); return 0; }'},tests:[{input:'8',expected:'Even'},{input:'7',expected:'Odd'},{input:'0',expected:'Even'}],hint:'Use the remainder operator % with 2.'},
{id:'largest',title:'Largest of three numbers',topic:'Conditionals',level:'Beginner',description:'Read three integers and print the largest.',examples:'Input: 4 9 2 → Output: 9',starter:{javascript:"const fs = require('fs');\nconst nums = fs.readFileSync(0, 'utf8').trim().split(/\\s+/).map(Number);\nconsole.log(Math.max(...nums));",python:"a, b, c = map(int, input().split())\nprint(max(a, b, c))",c:'#include <stdio.h>\nint main(void) { int a,b,c,m; if(scanf("%d %d %d",&a,&b,&c)!=3)return 0; m=a>b?a:b; m=m>c?m:c; printf("%d\\n",m); return 0; }'},tests:[{input:'4 9 2',expected:'9'},{input:'-5 -2 -9',expected:'-2'},{input:'6 6 1',expected:'6'}],hint:'Compare the three values, or use the language’s maximum function.'},
{id:'factorial',title:'Factorial of a number',topic:'Loops',level:'Beginner',description:'Print n factorial for 0 ≤ n ≤ 12.',examples:'Input: 5 → Output: 120',starter:{javascript:"const fs = require('fs');\nconst n = Number(fs.readFileSync(0, 'utf8').trim());\nlet result = 1; for (let i = 2; i <= n; i++) result *= i;\nconsole.log(result);",python:"n = int(input())\nresult = 1\nfor i in range(2, n + 1):\n    result *= i\nprint(result)",c:'#include <stdio.h>\nint main(void) { int n; long long r=1; if(scanf("%d",&n)!=1)return 0; for(int i=2;i<=n;i++)r*=i; printf("%lld\\n",r); return 0; }'},tests:[{input:'5',expected:'120'},{input:'0',expected:'1'},{input:'1',expected:'1'}],hint:'Start with 1 and multiply by every integer from 2 through n.'},
{id:'prime',title:'Prime number check',topic:'Loops',level:'Beginner',description:'Print Prime if n is prime, otherwise Not prime.',examples:'Input: 7 → Output: Prime',starter:{javascript:"const fs = require('fs');\nconst n = Number(fs.readFileSync(0, 'utf8').trim());\nlet prime = n >= 2; for (let i = 2; i * i <= n; i++) if (n % i === 0) prime = false;\nconsole.log(prime ? 'Prime' : 'Not prime');",python:"n = int(input())\nprime = n >= 2\nfor i in range(2, int(n ** 0.5) + 1):\n    if n % i == 0:\n        prime = False\n        break\nprint('Prime' if prime else 'Not prime')",c:'#include <stdio.h>\nint main(void) { int n,p=1; if(scanf("%d",&n)!=1)return 0; if(n<2)p=0; for(int i=2;i*i<=n;i++)if(n%i==0){p=0;break;} puts(p?"Prime":"Not prime"); return 0; }'},tests:[{input:'7',expected:'Prime'},{input:'1',expected:'Not prime'},{input:'12',expected:'Not prime'}],hint:'Numbers below 2 are not prime. Check divisors up to the square root of n.'},
{id:'fibonacci',title:'Nth Fibonacci number',topic:'Loops',level:'Beginner',description:'Print the zero-indexed Fibonacci number F(n), where F(0)=0 and F(1)=1.',examples:'Input: 7 → Output: 13',starter:{javascript:"const fs = require('fs');\nconst n = Number(fs.readFileSync(0, 'utf8').trim());\nlet a = 0, b = 1; for (let i = 0; i < n; i++) [a, b] = [b, a + b];\nconsole.log(a);",python:"n = int(input())\na, b = 0, 1\nfor _ in range(n):\n    a, b = b, a + b\nprint(a)",c:'#include <stdio.h>\nint main(void) { int n; long long a=0,b=1,t; if(scanf("%d",&n)!=1)return 0; for(int i=0;i<n;i++){t=a+b;a=b;b=t;} printf("%lld\\n",a); return 0; }'},tests:[{input:'7',expected:'13'},{input:'0',expected:'0'},{input:'1',expected:'1'}],hint:'Track the previous two values and update them n times.'},
{id:'reverse',title:'Reverse a string',topic:'Strings',level:'Beginner',description:'Read one line and print it reversed.',examples:'Input: study → Output: yduts',starter:{javascript:"const fs = require('fs');\nconst text = fs.readFileSync(0, 'utf8').replace(/\\r?\\n$/, '');\nconsole.log([...text].reverse().join(''));",python:"text = input()\nprint(text[::-1])",c:'#include <stdio.h>\n#include <string.h>\nint main(void) { char s[1000]; if(!fgets(s,sizeof(s),stdin))return 0; int n=(int)strlen(s); if(n&&s[n-1]==\'\\n\')s[--n]=\'\\0\'; for(int i=n-1;i>=0;i--)putchar(s[i]); putchar(\'\\n\'); return 0; }'},tests:[{input:'study',expected:'yduts'},{input:'level',expected:'level'},{input:'\n',expected:''}],hint:'Visit the characters from the end to the beginning.'},
{id:'palindrome',title:'Palindrome checker',topic:'Strings',level:'Beginner',description:'Print Palindrome if the input word reads the same backwards; otherwise Not palindrome.',examples:'Input: level → Output: Palindrome',starter:{javascript:"const fs = require('fs');\nconst s = fs.readFileSync(0, 'utf8').trim();\nconsole.log(s === [...s].reverse().join('') ? 'Palindrome' : 'Not palindrome');",python:"s = input().strip()\nprint('Palindrome' if s == s[::-1] else 'Not palindrome')",c:'#include <stdio.h>\n#include <string.h>\nint main(void) { char s[1000]; if(!fgets(s,sizeof(s),stdin))return 0; int n=(int)strlen(s); if(n&&s[n-1]==\'\\n\')s[--n]=\'\\0\'; int ok=1; for(int i=0;i<n/2;i++)if(s[i]!=s[n-1-i])ok=0; puts(ok?"Palindrome":"Not palindrome"); return 0; }'},tests:[{input:'level',expected:'Palindrome'},{input:'study',expected:'Not palindrome'},{input:'madam',expected:'Palindrome'}],hint:'Compare the original string with its reversed version.'},
{id:'vowels',title:'Count vowels',topic:'Strings',level:'Beginner',description:'Count vowels (a, e, i, o, u), ignoring case.',examples:'Input: Education → Output: 5',starter:{javascript:"const fs = require('fs');\nconst s = fs.readFileSync(0, 'utf8').trim().toLowerCase();\nconsole.log([...s].filter(ch => 'aeiou'.includes(ch)).length);",python:"s = input().lower()\nprint(sum(1 for ch in s if ch in 'aeiou'))",c:'#include <stdio.h>\n#include <ctype.h>\nint main(void) { char s[1000]; if(!fgets(s,sizeof(s),stdin))return 0; int count=0; for(int i=0;s[i];i++){char c=(char)tolower((unsigned char)s[i]); if(c==\'a\'||c==\'e\'||c==\'i\'||c==\'o\'||c==\'u\')count++;} printf("%d\\n",count); return 0; }'},tests:[{input:'Education',expected:'5'},{input:'rhythm',expected:'0'},{input:'APPLE',expected:'2'}],hint:'Normalize case, then count characters that are in aeiou.'},
{id:'search',title:'Linear search',topic:'Arrays',level:'Beginner',description:'Input line 1: n. Input line 2: n space-separated integers. Input line 3: target. Print its zero-based index, or -1 if missing.',examples:'Input: 4\n4 8 12 16\n12 → Output: 2',starter:{javascript:"const fs = require('fs');\nconst lines = fs.readFileSync(0, 'utf8').trim().split(/\\r?\\n/);\nconst n = Number(lines[0]); const nums = lines[1].trim().split(/\\s+/).slice(0,n).map(Number); const target = Number(lines[2]);\nconsole.log(nums.indexOf(target));",python:"n = int(input())\nnums = list(map(int, input().split()))[:n]\ntarget = int(input())\nprint(nums.index(target) if target in nums else -1)",c:'#include <stdio.h>\nint main(void) { int n,a[1000],t; if(scanf("%d",&n)!=1)return 0; for(int i=0;i<n&&i<1000;i++)if(scanf("%d",&a[i])!=1)return 0; if(scanf("%d",&t)!=1)return 0; for(int i=0;i<n&&i<1000;i++)if(a[i]==t){printf("%d\\n",i);return 0;} puts("-1"); return 0; }'},tests:[{input:'4\n4 8 12 16\n12',expected:'2'},{input:'3\n3 5 7\n9',expected:'-1'},{input:'3\n10 20 30\n10',expected:'0'}],hint:'Scan each array element from left to right and stop at the first match.'},
{id:'sumarray',title:'Sum an array',topic:'Arrays',level:'Beginner',description:'Read n followed by n integers; print their sum.',examples:'Input: 4\n1 2 3 4 → Output: 10',starter:{javascript:"const fs = require('fs');\nconst values = fs.readFileSync(0, 'utf8').trim().split(/\\s+/).map(Number);\nconsole.log(values.slice(1, values[0] + 1).reduce((a, b) => a + b, 0));",python:"n = int(input())\nnums = list(map(int, input().split()))\nprint(sum(nums[:n]))",c:'#include <stdio.h>\nint main(void) { int n,x; long long sum=0; if(scanf("%d",&n)!=1)return 0; for(int i=0;i<n;i++){if(scanf("%d",&x)!=1)return 0;sum+=x;} printf("%lld\\n",sum); return 0; }'},tests:[{input:'4\n1 2 3 4',expected:'10'},{input:'3\n-1 5 2',expected:'6'},{input:'1\n9',expected:'9'}],hint:'Read the count first, then accumulate each of the next n values.'}
];
type WandboxCompiler = {name:string;language?:string;version?:string;"display-name"?:string};
let wandboxCompilerList: Promise<WandboxCompiler[]> | null = null;
async function getWandboxCompilers(): Promise<WandboxCompiler[]> {
  if (!wandboxCompilerList) {
    wandboxCompilerList = fetch('https://wandbox.org/api/list.json', { headers: { Accept: 'application/json' } })
      .then(async response => {
        if (!response.ok) throw new Error(`Compiler list unavailable (HTTP ${response.status}). Please retry.`);
        const data = await response.json();
        if (!Array.isArray(data)) throw new Error('The compiler service returned an unexpected compiler list.');
        return data as WandboxCompiler[];
      })
      .catch(error => { wandboxCompilerList = null; throw error; });
  }
  return wandboxCompilerList;
}
async function executeRemote(language:'javascript'|'python'|'c',code:string,input:string) {
  const compilers = await getWandboxCompilers();
  const normalized = (value:string|undefined) => (value || '').toLowerCase().replace(/[^a-z0-9]/g,'');
  const matches = compilers.filter(c => {
    const lang = normalized(c.language);
    const name = normalized(c.name);
    if (language === 'javascript') return (lang === 'javascript' || lang === 'javascriptc') && name.includes('nodejs');
    if (language === 'python') return lang === 'python' && (name.includes('cpython') || name.includes('python'));
    return lang === 'c' && (name.includes('gcc') || name.includes('clang')) && !name.includes('cpp');
  });
  if (!matches.length) throw new Error(`No ${language === 'javascript' ? 'Node.js' : language === 'python' ? 'Python' : 'C'} compiler is currently available. Please try again later.`);
  // Prefer stable, non-head compilers; use the service's advertised list rather than a hard-coded version.
  const compiler = matches.find(c => !/head|experimental|nightly/i.test(c.name)) || matches[0];
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 20000);
  try {
    const response = await fetch('https://wandbox.org/api/compile.json', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({ code, compiler: compiler.name, stdin: input, save: false })
    });
    if (!response.ok) throw new Error(`Compiler service returned HTTP ${response.status}. Please retry in a moment.`);
    const data = await response.json();
    const compileError = String(data.compiler_error || '').trim();
    const programError = String(data.program_error || '').trim();
    const output = String(data.program_output ?? '').replace(/\r/g, '').trimEnd();
    if (compileError) throw new Error(compileError);
    if (programError) throw new Error(programError);
    if (data.status && String(data.status) !== '0') throw new Error(output || `Program exited with status ${data.status}.`);
    return output;
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') throw new Error('The code runner took too long to respond. Please try again.');
    if (error instanceof TypeError) throw new Error('Could not reach the online compiler. Check your internet connection, then retry.');
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}
export function CodeLabPage({onToast}:{onToast:ToastFn}){
 const [challengeId,setChallengeId]=useState('sum');const [language,setLanguage]=useState<'javascript'|'python'|'c'>('javascript');const [code,setCode]=useState(()=>readLocal('sf_codelab_code_sum_javascript',challenges[0].starter.javascript));const [hint,setHint]=useState(false);const [busy,setBusy]=useState(false);const [result,setResult]=useState<{message:string;results:{index:number;input:string;actual:string;expected:string;pass:boolean}[];error:boolean}>({message:'Run your solution to execute every test case in the selected language.',results:[],error:false});const challenge=challenges.find(c=>c.id===challengeId)||challenges[0];
 useEffect(()=>{localStorage.setItem(`sf_codelab_code_${challengeId}_${language}`,code);},[code,challengeId,language]);
 function choose(id:string){const c=challenges.find(x=>x.id===id)||challenges[0];setChallengeId(id);setCode(readLocal(`sf_codelab_code_${id}_${language}`,c.starter[language]));setResult({message:'Run your solution to execute every test case in the selected language.',results:[],error:false});setHint(false);}
 function changeLanguage(next:'javascript'|'python'|'c'){setLanguage(next);setCode(readLocal(`sf_codelab_code_${challengeId}_${next}`,challenge.starter[next]));setResult({message:'Run your solution to execute every test case in this language.',results:[],error:false});}
 async function run(){if(busy)return;setBusy(true);setResult({message:`Compiling/running ${challenge.tests.length} test cases in ${language==='javascript'?'JavaScript':language==='python'?'Python':'C'}…`,results:[],error:false});try{const results=[];for(let i=0;i<challenge.tests.length;i++){const t=challenge.tests[i];const actual=await executeRemote(language,code,t.input);results.push({index:i+1,input:t.input,actual,expected:t.expected,pass:actual===t.expected});setResult({message:`Completed ${i+1} of ${challenge.tests.length} test cases.`,results:[...results],error:false});}const passed=results.filter(r=>r.pass).length;setResult({message:passed===results.length?'All test cases passed. Excellent work!':`${passed} of ${results.length} test cases passed. Check the input/output details below.`,results,error:false});if(passed===results.length)onToast('Challenge completed — all test cases passed!');}catch(e){setResult({message:e instanceof Error?e.message:'The code runner could not execute your program.',results:[],error:true});}finally{setBusy(false);}}
 return <div className="feature-page codelab-v2"><div className="page-intro"><div><div className="eyebrow">PRACTISE BY BUILDING</div><h1>CodeLab</h1><p>Practice eleven core programming patterns and run test cases in JavaScript, Python, and C.</p></div><span className="codelab-level"><Zap size={15}/> {challenges.length} guided programs</span></div><div className="feature-hero codelab-hero"><div className="feature-hero-icon"><Code2 size={25}/></div><div><span className="feature-kicker">MULTI-LANGUAGE WORKSPACE</span><h2>Write. Compile. Validate.</h2><p>Each program runs against three input/output test cases in your selected language.</p></div><div className="feature-hero-metric"><strong>3</strong><span>supported languages</span></div></div><div className="codelab-layout"><section className="panel challenge-panel"><div className="panel-heading"><div><h3>Practice library</h3><p>Choose a beginner program.</p></div><Flag size={18}/></div>{challenges.map((c,i)=><button key={c.id} className={`challenge-item ${challengeId===c.id?'active':''}`} onClick={()=>choose(c.id)}><span className="challenge-number">{String(i+1).padStart(2,'0')}</span><span><strong>{c.title}</strong><small>{c.topic} · {c.level}</small></span><ChevronRight size={15}/></button>)}</section><section className="panel code-editor-panel"><div className="code-challenge-head"><div><span className="feature-kicker">{challenge.topic.toUpperCase()} · {challenge.level.toUpperCase()}</span><h2>{challenge.title}</h2><p>{challenge.description}</p><small className="code-examples">{challenge.examples}</small></div><label className="language-select">Language<select className="select-field" value={language} onChange={e=>changeLanguage(e.target.value as 'javascript'|'python'|'c')}><option value="javascript">JavaScript (Node.js)</option><option value="python">Python 3</option><option value="c">C (GCC)</option></select></label></div><div className="code-editor-top"><span><i/><i/><i/> <strong>main.{language==='javascript'?'js':language==='python'?'py':'c'}</strong></span><button className="text-button" onClick={()=>{setCode(challenge.starter[language]);setResult({message:'Starter solution restored.',results:[],error:false});}}>Reset code</button></div><textarea className="code-editor" spellCheck={false} value={code} onChange={e=>setCode(e.target.value)} aria-label="Code editor"/><div className="code-editor-actions"><button className="btn btn-primary" disabled={busy} onClick={run}><Terminal size={16}/>{busy?'Running…':'Run all test cases'}</button><button className="btn btn-secondary" onClick={()=>setHint(v=>!v)}><Lightbulb size={15}/>{hint?'Hide hint':'Show hint'}</button><span className="code-language-note">{busy?'Execution in progress':'Remote sandbox · no setup needed'}</span></div>{hint&&<div className="hint-callout"><Lightbulb size={16}/><p>{challenge.hint}</p></div>}<div className={`code-output ${result.error?'output-error':result.results.length&&!result.error?'output-done':''}`}><div className="code-output-head"><strong><Terminal size={15}/> Test results</strong>{result.results.length>0&&<span>{Math.round(result.results.filter(r=>r.pass).length/result.results.length*100)}% passed</span>}</div><p>{result.message}</p>{result.results.length>0&&<div className="test-result-list">{result.results.map(r=><div className="test-result-row" key={r.index}><span className={r.pass?'test-pass':'test-fail'}>{r.pass?<CheckCircle2 size={15}/>:<X size={15}/>} Test {r.index}</span><span>Input: <code>{r.input||'(empty)'}</code></span><span>Expected: <code>{r.expected}</code></span><span>Actual: <code>{r.actual||'(empty)'}</code></span></div>)}</div>}</div><div className="feature-info-note code-safety-note"><ShieldCheck size={16}/><span>Code executes on the Wandbox online compiler service. Internet access is required; never paste passwords, API keys, or private data into the editor. A temporary service outage may prevent tests from running.</span></div></section></div></div>;
}
